    icon:'<svg viewBox="0 0 48 48" width="34" height="34" fill="none" stroke="#1F618D" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round"><path d="M24 12c-3-2.5-8-3-14-2v24c6-1 11 0 14 2.5"/><path d="M24 12c3-2.5 8-3 14-2v24c-6-1-11 0-14 2.5"/><path d="M24 12v24.5"/><path d="M30 16l4-6"/></svg>',
